-- COSMOS content from the EVE University wiki (agents + missions).
-- The client does not ship COSMOS mission texts (resCOSMOS holds only models),
-- and the previous 92xxx rows were a synthetic skeleton.
-- +migrate Up
CREATE TABLE IF NOT EXISTS cosmosAgentMissions (
  agentID int(10) unsigned NOT NULL,
  missionID int(10) unsigned NOT NULL,
  step tinyint(3) unsigned NOT NULL,
  PRIMARY KEY (agentID, step),
  UNIQUE KEY (missionID)
) ENGINE=InnoDB;

-- drop the synthetic COSMOS set
DELETE FROM cosmosAgentMissions;
DELETE FROM agtOffers WHERE missionID BETWEEN 92000 AND 92207;
DELETE FROM missionObjectives WHERE missionID BETWEEN 92000 AND 92207;
DELETE FROM agtMissions WHERE id BETWEEN 92000 AND 92207;
DELETE FROM agtAgents WHERE agentTypeID=12;

-- COSMOS agents live in space in the SDE; our client talks to agents at stations,
-- so dock them at a station in their system (fallback: constellation, then region)
UPDATE agtAgents SET level=4 WHERE agentTypeID=8 AND level>4
  AND locationID BETWEEN 30000000 AND 30999999;
UPDATE agtAgents a
  JOIN (SELECT solarSystemID, MIN(stationID) AS sid FROM staStations GROUP BY solarSystemID) s
    ON s.solarSystemID = a.locationID
  SET a.locationID = s.sid
  WHERE a.agentTypeID=8 AND a.locationID BETWEEN 30000000 AND 30999999;
UPDATE agtAgents a
  JOIN mapSolarSystems ms ON ms.solarSystemID = a.locationID
  JOIN (SELECT ms2.constellationID, MIN(st.stationID) AS sid FROM staStations st
          JOIN mapSolarSystems ms2 ON ms2.solarSystemID = st.solarSystemID
        GROUP BY ms2.constellationID) c ON c.constellationID = ms.constellationID
  SET a.locationID = c.sid
  WHERE a.agentTypeID=8 AND a.locationID BETWEEN 30000000 AND 30999999;
UPDATE agtAgents a
  JOIN mapSolarSystems ms ON ms.solarSystemID = a.locationID
  JOIN (SELECT ms2.regionID, MIN(st.stationID) AS sid FROM staStations st
          JOIN mapSolarSystems ms2 ON ms2.solarSystemID = st.solarSystemID
        GROUP BY ms2.regionID) r ON r.regionID = ms.regionID
  SET a.locationID = r.sid
  WHERE a.agentTypeID=8 AND a.locationID BETWEEN 30000000 AND 30999999;

-- ensure every COSMOS agent has a name row (LoadAgentData needs a bloodline typeID)
INSERT IGNORE INTO chrNPCCharacters
  (characterID, characterName, description, typeID, gender, corporationID, stationID, solarSystemID, constellationID, regionID)
