UPDATE chrNPCCharacters c
  JOIN agtAgents a ON a.agentID = c.characterID
  LEFT JOIN staStations s ON s.stationID = a.locationID
  SET c.corporationID = a.corporationID, c.stationID = a.locationID,
      c.solarSystemID = IFNULL(s.solarSystemID, c.solarSystemID),
      c.constellationID = IFNULL(s.constellationID, c.constellationID),
      c.regionID = IFNULL(s.regionID, c.regionID)
  WHERE a.agentTypeID=8;

